import { Table, GenericColumn, GuidColumn } from '../../db'

export const sysauto_script = Table({
    allowWebServiceAccess: true,
    extends: 'sysauto',
    extensible: true,
    label: 'Scheduled Script Execution',
    name: 'sysauto_script',
    schema: {
        script: GenericColumn({
            columnType: 'script_plain',
            label: 'Run this script',
            maxLength: 8000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
    textIndex: true,
})
